//! File size ratchet. A Rust source file under `crates/*/src` may not exceed `LIMIT` lines,
//! except the files listed in `metrics/file-sizes.toml`, each of which may not grow past its own
//! cap. A cap only goes down: split the file (see `docs/codemap.md`) and lower or delete the row.
//! Raising a cap needs the owner.
//!
//! Exempt: generated files (one of the first five lines holds `@generated` or `Generated by`)
//! and everything under `crates/*/tests`, `crates/*/examples` and `crates/*/benches`.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

const LIMIT: usize = 3000;
const TABLE: &str = "metrics/file-sizes.toml";

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .unwrap()
}

/// The `"path" = N` rows of the table; `#` starts a comment.
fn parse_table(text: &str) -> BTreeMap<String, usize> {
    let mut caps = BTreeMap::new();
    for (n, line) in text.lines().enumerate() {
        let line = line.split('#').next().unwrap().trim();
        if line.is_empty() {
            continue;
        }
        let (path, cap) = line
            .split_once('=')
            .unwrap_or_else(|| panic!("{TABLE}:{}: expected \"path\" = N", n + 1));
        let path = path.trim().trim_matches('"').to_string();
        let cap = cap
            .trim()
            .parse()
            .unwrap_or_else(|_| panic!("{TABLE}:{}: the cap is not a number", n + 1));
        assert!(
            caps.insert(path.clone(), cap).is_none(),
            "{TABLE}:{}: {path} is listed twice",
            n + 1
        );
    }
    caps
}

fn is_generated(text: &str) -> bool {
    text.lines()
        .take(5)
        .any(|l| l.contains("@generated") || l.contains("Generated by"))
}

/// Failure messages for `files` (path, line count, generated) against the table.
fn violations(files: &[(String, usize, bool)], caps: &BTreeMap<String, usize>) -> Vec<String> {
    let mut out = Vec::new();
    for (path, lines, generated) in files {
        if *generated {
            continue;
        }
        match caps.get(path) {
            None if *lines > LIMIT => out.push(format!(
                "{path}: {lines} lines, limit {LIMIT}. Split the file (see docs/codemap.md) \
                 instead of listing it; adding a row to {TABLE} needs the owner."
            )),
            Some(cap) if lines > cap => out.push(format!(
                "{path}: {lines} lines, cap {cap}. Split the file (see docs/codemap.md) \
                 instead of raising the cap; raising a cap needs the owner."
            )),
            _ => {}
        }
    }
    for path in caps.keys() {
        if !files.iter().any(|(p, _, _)| p == path) {
            out.push(format!(
                "{path}: listed in {TABLE} but not a source file; delete the row."
            ));
        }
    }
    out
}

/// Notes for listed files that shrank: the cap should follow.
fn lowerable(files: &[(String, usize, bool)], caps: &BTreeMap<String, usize>) -> Vec<String> {
    files
        .iter()
        .filter_map(|(path, lines, _)| {
            let cap = caps.get(path)?;
            (lines < cap).then(|| {
                if *lines <= LIMIT {
                    format!("{path}: now {lines} lines; delete its row in {TABLE}")
                } else {
                    format!("{path}: now {lines} lines; lower its cap from {cap} to {lines} in {TABLE}")
                }
            })
        })
        .collect()
}

fn collect(dir: &Path, root: &Path, out: &mut Vec<(String, usize, bool)>) {
    for entry in std::fs::read_dir(dir).unwrap() {
        let path = entry.unwrap().path();
        if path.is_dir() {
            collect(&path, root, out);
        } else if path.extension().is_some_and(|e| e == "rs") {
            let text = std::fs::read_to_string(&path).unwrap();
            let rel = path.strip_prefix(root).unwrap().to_string_lossy().replace('\\', "/");
            out.push((rel, text.lines().count(), is_generated(&text)));
        }
    }
}

fn source_files(root: &Path) -> Vec<(String, usize, bool)> {
    let mut out = Vec::new();
    for krate in std::fs::read_dir(root.join("crates")).unwrap() {
        let src = krate.unwrap().path().join("src");
        if src.is_dir() {
            collect(&src, root, &mut out);
        }
    }
    out.sort();
    out
}

#[test]
fn no_source_file_grows_past_its_cap() {
    let root = root();
    let table = std::fs::read_to_string(root.join(TABLE)).unwrap_or_else(|e| panic!("{TABLE}: {e}"));
    let caps = parse_table(&table);
    let files = source_files(&root);
    for note in lowerable(&files, &caps) {
        eprintln!("note: {note}");
    }
    let bad = violations(&files, &caps);
    assert!(bad.is_empty(), "file size ratchet:\n{}", bad.join("\n"));
}

fn f(path: &str, lines: usize) -> (String, usize, bool) {
    (path.to_string(), lines, false)
}

#[test]
fn an_unlisted_file_over_the_limit_fails() {
    let bad = violations(&[f("crates/a/src/big.rs", 3001)], &BTreeMap::new());
    assert_eq!(bad.len(), 1);
    assert!(
        bad[0].contains("crates/a/src/big.rs: 3001 lines, limit 3000"),
        "{bad:?}"
    );
}

#[test]
fn a_file_at_the_limit_passes() {
    assert!(violations(&[f("crates/a/src/ok.rs", 3000)], &BTreeMap::new()).is_empty());
}

#[test]
fn a_listed_file_may_not_grow_but_may_shrink() {
    let caps = parse_table("\"crates/a/src/big.rs\" = 4000 # why\n");
    let grown = violations(&[f("crates/a/src/big.rs", 4001)], &caps);
    assert_eq!(grown.len(), 1);
    assert!(grown[0].contains("4001 lines, cap 4000"), "{grown:?}");
    assert!(grown[0].contains("raising a cap needs the owner"), "{grown:?}");
    let files = [f("crates/a/src/big.rs", 3500)];
    assert!(violations(&files, &caps).is_empty());
    assert!(lowerable(&files, &caps)[0].contains("lower its cap from 4000 to 3500"));
}

#[test]
fn a_row_for_a_missing_file_fails() {
    let caps = parse_table("\"crates/a/src/gone.rs\" = 4000\n");
    assert_eq!(violations(&[], &caps).len(), 1);
}

#[test]
fn generated_files_are_exempt() {
    assert!(is_generated("// @generated by x\nfn a() {}\n"));
    assert!(is_generated("// Generated by `tool`\n"));
    assert!(!is_generated("\n\n\n\n\n// Generated by\n"));
    let files = [("crates/a/src/gen.rs".to_string(), 9000, true)];
    assert!(violations(&files, &BTreeMap::new()).is_empty());
}
